// Parse output dari AI Agent (independen dari Parse AI & Notify)
const raw = $('AI Agent').item.json.output;

let moments;
try {
  const match = raw.match(/\[[\s\S]*\]/);
  if (!match) throw new Error('Format JSON tidak ditemukan dalam output AI');
  moments = JSON.parse(match[0]);
} catch (err) {
  throw new Error('⚠️ AI gagal menghasilkan output yang valid. Error: ' + err.message);
}

const original_text = $('Telegram Trigger').item.json.message.text.trim();
const parts = original_text.split(' ');
const yt_url = parts[0];
const range = parts[1] && parts[1].includes('-') ? parts[1] : null;
const isGaming = original_text.toUpperCase().includes('GAMING');
const mode = isGaming ? "gaming" : "normal";
const chatId = $('Telegram Trigger').item.json.message.chat.id;

// Split menjadi 3 item — satu per klip
return moments.map((m, i) => ({
  json: {
    url: yt_url,
    start: m.start,
    end: m.end,
    caption: m.caption,
    mode: mode,
    nomor: m.nomor,
    score: m.score,
    tipe: m.tipe,
    alasan: m.alasan,
    total: moments.length,
    chatId: chatId,
    index: i
  }
}));

// Agregasi 3 item menjadi 1 batch request
const items = $input.all();

return [{
  json: {
    url: items[0].json.url,
    clips: items.map(item => ({
      start: item.json.start,
      end: item.json.end
    })),
    mode: items[0].json.mode
  }
}];

// Split batch response menjadi item per-klip
const batchResult = $input.first().json;
const originalItems = $('Split to 3 Clips').all();

if (!batchResult.clips || !Array.isArray(batchResult.clips)) {
  throw new Error('Batch response tidak valid: ' + JSON.stringify(batchResult));
}

// Map setiap clip hasil ke item, gabung dengan metadata dari Split node
return batchResult.clips.map((clip, i) => {
  const orig = originalItems[i] || { json: {} };
  return {
    json: {
      file: clip.file || null,
      size_mb: clip.size_mb || 0,
      status: clip.status || 'error',
      error: clip.error || null,
      caption: orig.json.caption || '',
      chatId: orig.json.chatId || items[0].json.chatId,
      nomor: i + 1,
      start: orig.json.start || '',
      end: orig.json.end || '',
      mode: orig.json.mode || batchResult.mode || 'normal'
    }
  };
});

// Helper: truncate string tanpa memotong emoji di tengah
const safeTruncate = (str, maxLen) => {
  const chars = Array.from(str);
  return chars.length > maxLen ? chars.slice(0, maxLen).join('') + '...' : str;
};

// Agregasi hasil semua klip (baca dari Split Batch Result)
const items = $("Split Batch Result").all();
const total = items.length;

// Deteksi item sukses: punya field 'file' tanpa error
const successItems = items.filter(i => {
  const j = i.json;
  return j.file && j.status === 'success';
});
const failedItems = items.filter(i => {
  const j = i.json;
  return !j.file || j.status !== 'success';
});

const success = successItems.length;
const failed = failedItems.length;

// Fallback chatId
const firstItem = successItems[0] || items[0];
const chatId = (firstItem && firstItem.json.chatId) ? firstItem.json.chatId : '6485651144';

let msg = `✅ *Selesai!* ${success}/${total} klip berhasil dipotong.\n\n`;

successItems.forEach(item => {
  msg += `🎬 *Klip #${item.json.nomor}* ⏱ ${item.json.start}-${item.json.end}\n`;
  msg += `📝 ${safeTruncate(item.json.caption, 60)}...\n\n`;
});

if (failed > 0) {
  msg += `⚠️ *${failed} klip gagal diproses.*\n`;
  failedItems.forEach(item => {
    msg += `❌ Klip #${item.json.nomor}: ${item.json.error || 'Unknown error'}\n`;
  });
  msg += `\nSilakan coba lagi atau gunakan video lain.\n`;
}

msg += `🔗 Kirim link YouTube lain untuk melanjutkan!`;

return [{
  json: {
    chatId: chatId,
    text: msg
  }
}];

// Parse output AI + extract facecam position + langsung aggregate ke 1 item
  const raw = $('AI Agent GAMING5').item.json.output;

  const safeTruncate = (str, maxLen) => {
    if (!str) return '';
    const chars = Array.from(str);
    return chars.length > maxLen ? chars.slice(0, maxLen).join('') + '...' : str;
  };

  // Sanitasi MINIMAL — hanya hal yang 100% aman
  function sanitizeJSON(text) {
    // 1. Hapus markdown code fences
    text = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '');

    // 2. Hapus trailing comma sebelum ] atau }
    text = text.replace(/,(\s*[\]}])/g, '$1');

    return text;
  }

  // Cari JSON array dengan regex GREEDY
  const match = raw.match(/\[[\s\S]*\]/);
  if (!match) throw new Error('Format JSON tidak ditemukan dalam output AI');

  let jsonText = match[0];
  let moments;

  // Coba 1: parse langsung (tanpa sanitasi)
  try {
    moments = JSON.parse(jsonText);
  } catch (err1) {
    // Coba 2: sanitasi lalu parse
    try {
      jsonText = sanitizeJSON(jsonText);
      moments = JSON.parse(jsonText);
    } catch (err2) {
      // Coba 3: bersihin semua karakter non-printable + coba lagi
      try {
        jsonText = jsonText.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F]/g, ' ');
        moments = JSON.parse(jsonText);
      } catch (err3) {
        const preview = raw ? raw.substring(0, 500) : '(empty)';
        throw new Error('AI gagal menghasilkan output valid: ' + err3.message + ' | Raw: ' + preview);
      }
    }
  }

  if (!Array.isArray(moments) || moments.length === 0) {
    throw new Error('Output bukan array atau array kosong');
  }

  const originalText = $('Telegram Trigger').item.json.message.text.trim();
  const parts = originalText.split(' ');
  const yt_url = parts[0];

  const textUpper = originalText.toUpperCase();
  let facecamPosition = 'btmleft';
  if (textUpper.includes('TOPRIGHT')) facecamPosition = 'topright';
  else if (textUpper.includes('TOPLEFT')) facecamPosition = 'topleft';
  else if (textUpper.includes('BTMRIGHT')) facecamPosition = 'btmright';
  else if (textUpper.includes('BTMLEFT')) facecamPosition = 'btmleft';

  const chatId = $('Telegram Trigger').item.json.message.chat.id;

  // Build notifikasi
  let notifyMsg = '\u{1F3AE} *5 Momen Gaming Ditemukan!*\n';
  notifyMsg += '\u{1F4CD} Facecam: ' + facecamPosition.toUpperCase() + '\n\n';

  moments.forEach((m, i) => {
    const tipe = m.tipe || m.kategori || 'GAMING';
    notifyMsg += '*' + (i + 1) + '.* \u23F1 ' + m.start + ' - ' + m.end + ' | ' + tipe + '\n';
    notifyMsg += '\u{1F4DD} ' + safeTruncate(m.alasan, 100) + '\n';
    notifyMsg += '\u{1F3F7}\uFE0F ' + safeTruncate(m.caption, 60) + '\n\n';
  });

  notifyMsg += '\u23F3 Memproses kompilasi *' + moments.length + ' klip*...';
  notifyMsg += '\n\u{1F4F9} Video final akan dikirim via Google Drive.';

  return [{
    json: {
      url: yt_url,
      clips: moments.map(m => ({ start: m.start, end: m.end })),
      facecam_position: facecamPosition,
      chatId: chatId,
      notifyText: notifyMsg
    }
  }];
